def apply(inputs, premises):
    asset_names = inputs["asset_names"]
    asset_values = inputs["asset_values"]
    asset_kinds = inputs["asset_kinds"]
    federal_available = inputs["federal_available"]
    oregon_available = inputs["oregon_available"]
    result = {}
    count = min(len(asset_names), len(asset_values), len(asset_kinds))
    for i in range(count):
        name = asset_names[i]
        value = asset_values[i]
        kind = asset_kinds[i]
        claims = []
        if federal_available:
            if kind == "animal":
                claims = claims + [{"citation": premises["federal_animal_citation"], "claim_value": min(value, premises["federal_animal_cap"])}]
            claims = claims + [{"citation": premises["federal_wildcard_citation"], "claim_value": min(value, premises["federal_wildcard_cap"])}]
        if oregon_available:
            if kind == "animal":
                claims = claims + [{"citation": premises["oregon_animal_citation"], "claim_value": min(value, premises["oregon_animal_cap"])}]
            claims = claims + [{"citation": premises["oregon_wildcard_citation"], "claim_value": min(value, premises["oregon_wildcard_cap"])}]
            if kind == "firearm":
                claims = claims + [{"citation": premises["oregon_firearm_citation"], "claim_value": min(value, premises["oregon_firearm_cap"])}]
        result[name] = claims
    return {"claims_by_asset": result}

